"""Stateless calibrated ECTemp comparator for variant 3B. Stdlib only."""
import json, math
try:
    C=json.load(open('calib_cfg.json'))
except Exception:
    C={'a':1.1440452781193264,'b':-4.947024274335774,'c':0.0,'half':0.8,'lo_off':-0.8,'hi_off':0.8}
def clamp(x,a,b):
    return a if x<a else (b if x>b else x)
def ectemp(h):
    e=37.0; prev=e
    for r in h:
        prev=e
        x=r.get('hr'); hr=80.0 if x is None else float(x)
        x=r.get('skin_temp'); sk=34.0 if x is None else float(x)
        x=r.get('watts'); w=0.0 if x is None else float(x)
        target=36.7+0.012*(hr-70.0)+0.045*(sk-33.0)+0.001*w
        e+=0.08*(target-e)
    return e,prev
def predict(request):
    e,prev=ectemp(request['history'])
    if request.get('task')=='3A':
        e+=15.0*clamp(e-prev,-0.03,0.03)
    d=e-37.5
    p=float(C['a'])*e+float(C['b'])+float(C.get('c',0.0))*d*d
    p=clamp(p,35.0,41.0)
    if 'half' in C:
        lo=p-float(C['half']); hi=p+float(C['half'])
    else:
        lo=p+float(C['lo_off']); hi=p+float(C['hi_off'])
    if not hi>lo: lo,hi=p-0.5,p+0.5
    if hi-lo>5.0: lo,hi=p-2.5,p+2.5
    return {'mean':p,'lower':lo,'upper':hi}
